# Picard-lattice side: lattice generated by the 56 lines and h; Gram matrix; data for conic-class enumeration
import json, sympy as sp
edges = json.load(open('../../data/edges.json'))
n = 56
G = sp.zeros(n, n)
for i in range(n): G[i, i] = -2
for i, j in edges: G[i, j] = G[j, i] = 1
rk = G.rank(); print('rank of line Gram', rk)
# independent lines
I = []
cur = sp.zeros(0, n)
for i in range(n):
    t = cur.col_join(G[i, :])
    if t.rank() > cur.rows: cur = t; I.append(i)
    if len(I) == rk: break
GI = G.extract(I, I); assert GI.det() != 0
GIinv = GI.inv()
# h: pairing vector (1,...,1); coefficients on I
one = sp.ones(n, 1)
a = GIinv*one.extract(I, [0])
hh = (one.extract(I, [0]).T*a)[0]; print('h.h =', hh)
# check consistency: h.L_j = 1 for all j using coefficients a on I
chk = all(sum(a[k]*G[I[k], j] for k in range(rk)) == 1 for j in range(n)); print('h in Q-span of lines consistent:', chk)
print('denominators of h in line basis:', sorted(set(sp.denom(t) for t in a)))
# integer pairing vectors of generators: lines -> rows of G, h -> ones
rows = [list(G[i, :]) for i in range(n)] + [[1]*n]
rows = [[int(t) for t in r] for r in rows]
# Euclid row reduction (integer) to get a Z-basis of the row lattice
def zbasis(rows):
    rows = [r[:] for r in rows]; basis = []; col = 0; m = len(rows[0])
    for col in range(m):
        while True:
            nz = [r for r in rows if r[col] != 0]
            if len(nz) <= 1: break
            nz.sort(key=lambda r: abs(r[col])); p = nz[0]
            for r in nz[1:]:
                q = r[col]//p[col]
                for k in range(m): r[k] -= q*p[k]
        nz = [r for r in rows if r[col] != 0]
        if nz: basis.append(nz[0]); rows.remove(nz[0])
    return basis
B = zbasis(rows); print('lattice rank (basis size)', len(B))
Bm = sp.Matrix(B)
# Gram on basis: u.v = p_u[I]^T GIinv p_v[I]
BI = Bm.extract(list(range(len(B))), I)
Gram = (BI*GIinv*BI.T)
assert all(sp.denom(t) == 1 for t in Gram), 'non-integral lattice'
print('Gram integral; det =', Gram.det(), ' signature check later')
# h in basis coordinates: solve x*Bm = ones  (row combination)
hp = sp.Matrix([[1]*n])
x = sp.symbols('x0:%d' % len(B))
sol = sp.linsolve((Bm.T, hp.T), *x);
hx = list(list(sol)[0]); print('h coords integral:', all(sp.denom(t) == 1 for t in hx))
hx = sp.Matrix([hx]).T
print('check h.h =', (hx.T*Gram*hx)[0])
# P(x) = -x.x + (x.h)^2/2 ; 2P integral Gram:
hv = Gram*hx
P2 = -2*Gram + hv*hv.T
r = len(B)
with open('lat.txt', 'w') as f:
    f.write('%d\n' % r)
    for i in range(r): f.write(' '.join(str(P2[i, j]) for j in range(r))+'\n')
    f.write(' '.join(str(t) for t in hv)+'\n')
    f.write(' '.join(str(Gram[i, j]) for i in range(r) for j in range(r))+'\n')
# line coordinates in basis: need x_L with x_L * Bm = row of G  (to identify lines among found classes)
LX = []
for i in range(n):
    s = list(sp.linsolve((Bm.T, sp.Matrix(rows[i])), *x))[0]; LX.append([int(t) for t in s])
with open('lat_lines.txt', 'w') as f:
    for v in LX: f.write(' '.join(map(str, v))+'\n')
print('P2 positive definite? min eig (float):', min(sp.Matrix(P2).evalf().eigenvals().keys(), key=lambda e: sp.re(e)) if False else 'see pari')
